// ---------- backdrop ----------
export function bigCloud(seed: number, w = 64, h = 26) {
  const g = new Grid(w, h);
  const n = 3 + (seed % 2);
  for (let i = 0; i < n; i++) { const cx = 10 + (i + .5) * (w - 20) / n, r = 7 + hash(i, seed) * 5; g.disc(cx, h - r - 3 + hash(seed, i) * 3, r, 'w'); }
  g.rect(8, h - 9, w - 16, 7, 'w');
  g.map((c, x, y) => (c === 'w' && y > h - 6 ? 'c' : c));
  // a sleepy face on some clouds (Cat Mario wink)
  if (seed % 3 === 0) { const cx = (w >> 1) - 2, cy = h - 12; g.hline(cx - 4, cx - 2, cy, 'C').hline(cx + 3, cx + 5, cy, 'C').set(cx, cy + 2, 'C').set(cx + 1, cy + 3, 'C').set(cx + 2, cy + 2, 'C'); }
  return g.rows();
}
export function hills(seed: number, w: number, h: number, base: number, amp: number, a: string, b: string, top: string) {
  const g = new Grid(w, h);
  for (let x = 0; x < w; x++) {
    const t = x / w * Math.PI * 2;
    const y = Math.round(base - amp * (0.55 * Math.sin(t * 2 + seed) * 0.5 + 0.5) - amp * 0.45 * (Math.sin(t * 3 + seed * 2) * .5 + .5));
    g.vline(x, y, h - 1, a); g.set(x, y, top);
    for (let yy = y + 3; yy < h; yy++) if (hash(x >> 1, yy >> 1, seed) < .05) g.set(x, yy, b);
  }
  return g.rows();
}

